            "I had a thought to give you. The thought flew off. I stayed. Fair trade.",
            { t = "Morning. My wings are still cold. Give me a minute in the sun. Then I shall be dazzling at you.", when = { hour = "morning" } },
            { t = "Everything gold. You, gold. Me, more gold than usual, if such a thing can be. Hello.", when = { hour = "golden" } },
