            { t = "Early sun. I am flat on a warm stone with my wings wide, drinking heat. Don't mind me. Read. I am warming.", when = { hour = "morning" } },
            { t = "Dew on my wings like tiny lenses. Every drop has a garden inside. I shan't shake them off yet.", when = { hour = "morning" } },
            { t = "Noon. The air is thick and warm and holds me up. I hardly flap. I just lean on the day.", when = { hour = "day" } },
            { t = "High sun. My shadow is on your page. A small dark butterfly, reading. Leave my shadow there a moment.", when = { hour = "day" } },
            { t = "The light comes low now, through my wings. Did you know they do that? Stained glass. Tiny. Mine.", when = { hour = "golden" } },
            { t = "Gold hour. Everything slows. Even me. I open once, slowly, like the last line of something.", when = { hour = "golden" } },
            { t = "Night. I hang under a leaf with my wings together, edge on, nearly nothing. The moths have the late shift.", when = { hour = "night" } },
            { t = "Your lamp. A warm yellow. I am no moth, I shan't bump the glass. I only look, from my leaf, and think of fennel.", when = { hour = "night" } },
            { t = "Blossom coming down like wings that forgot how. I flew through a whole shower of petals. Nobody could tell which was me.", when = { season = "spring" } },
            { t = "New fennel. Feathery. Green. I don't eat leaves now, of course. I only stood on one a while. For old times.", when = { season = "spring" } },
            { t = "Thistles in flower. Purple. Sweet all the way down. I had three and lost my place in the afternoon.", when = { season = "summer" } },
            { t = "Heat. Long days. Wings never cold. This is the season I was folded up waiting for.", when = { season = "summer" } },
            { t = "Leaves letting go, yellow ones, turning in the air. They fly once. I waved. One waved back, I am nearly sure.", when = { season = "autumn" } },
            { t = "The light thins. The ivy is the last to flower. I sip there and remember bigger suppers. Read me something with summer in.", when = { season = "autumn" } },
            { t = "Cold. My kind sleep through this, folded in a case no longer than your thumbnail. I remember how. Hush. Fold. Trust.", when = { season = "winter" } },
            { t = "Frost on the window in feather shapes. Wing shapes. Somebody up there has been thinking of me.", when = { season = "winter" } },
            { t = "Blue. All the way up. I went as high as the chimney to look. Still blue. I came down to tell you.", when = { weather = "clear" } },
            { t = "Sun on my wings and every scale awake. On a day like this I am almost too much. Almost.", when = { weather = "clear" } },
