        level = {
            { t = "I land nearer now. Had you noticed? One flower closer each day. I am being subtle.", when = { level = 2, max_level = 2 } },
            { t = "I remembered you this morning before I remembered the sun. That is new.", when = { level = 2, max_level = 2 } },
            { t = "I open my wings when you come. All the way. I used to keep some back.", when = { level = 2, max_level = 2 } },
            { t = "I don't flit so much, near you. I stay whole minutes. Ask anyone. Nobody will believe you.", when = { level = 3, max_level = 3 } },
            { t = "You have seen me with my wings shut and plain, and you still looked. I thought only the colours were wanted.", when = { level = 3, max_level = 3 } },
            { t = "I told you about the caterpillar. I don't tell that. I am supposed to have always been lovely.", when = { level = 3, max_level = 3 } },
            { t = "Here is the truth. I am vain because I am afraid. Colours fade. I check mine every morning. Then I check for you.", when = { level = 4, max_level = 4 } },
            { t = "I forget nearly everything. Flowers. Days. My own way back. I have never once forgotten where you sit.", when = { level = 4, max_level = 4 } },
            { t = "Some part of me came apart in the chrysalis and never came back. Beside you I don't feel the gap.", when = { level = 4, max_level = 4 } },
            { t = "I thought I was made for light. For flowers. For being looked at. I think I was made to land here.", when = { level = 5, max_level = 5 } },
            { t = "If my colours go, every scale, will you still know me? You will. That is why I can ask out loud.", when = { level = 5, max_level = 5 } },
            { t = "I changed once, completely, in the dark. I shan't again. I like who I am beside you. I will stay this.", when = { level = 5, max_level = 5 } },
