    beats = {
        { id = "egg", at = 15, title = "A yellow pearl",
            text = "I began as one small yellow egg on a frond of fennel. Round. Alone. My mother tasted the leaf with her feet, to be sure, and then she was gone. I never saw her. I have her wings. I think that is how she stayed." },
        { id = "disguise", at = 40, title = "The disguise",
            text = "My first coat was black with a white smudge. I looked, and I shall say this once, like something a bird had dropped. That was the idea. Nobody eats that. I was safe and plain, and I have never forgiven the coat." },
        { id = "stripes", at = 80, title = "Stripes",
            text = "Then I grew green, with black bands and orange spots. Handsome, even then. If anyone bothered me I put out two orange horns that smelled dreadful. I miss the horns. Don't tell. One ought not to miss a smell." },
        { id = "fennel", at = 140, title = "Fennel",
            text = "All I did was eat. Fennel, all day, frond after frond, head down. I never once looked up. There was a sky the whole time. I think of that. A whole sky, and me, chewing." },
        { id = "stopping", at = 220, title = "The stopping",
            text = "One morning the fennel tasted of nothing. I walked, with no idea where. I found a stem, spun a small pad of silk, and tied myself on with a single thread round the middle. Then I waited. I did not know for what." },
        { id = "inside", at = 320, title = "Inside",
            text = "Inside the chrysalis I came apart. I can't put that more gently. Most of what I was went soft and was used for something else. I don't know who was minding me then. Somebody remembered the taste of fennel. So somebody was there." },
        { id = "winter", at = 450, title = "The winter in the case",
            text = "I spent a whole winter in there. Snow touched the outside. Rain was a far knocking. In the dark I kept seeing one thing, over and over: two pale wings opening, shutting, opening, covered in small black marks. I had never seen wings." },
        { id = "opening", at = 600, title = "The opening",
            text = "The case split in May. I climbed out wet and crumpled, wings like wrung cloth. I hung on and waited while they filled. An hour, more. Nothing can hurry that. Then they were dry, and wide, and yellow, and I looked at them for a long time." },
        { id = "up", at = 800, title = "Up",
            text = "The first flight was a fall that changed direction. Then air under me, and the fennel going small. I saw the whole garden at once, the wall, the lane, the fields. All that had been there. I flew for days, giddy with distance, landing nowhere for long." },
        { id = "pale_wings", at = 1050, title = "The pale wings",
            text = "Then, in this garden, I saw them. Two pale wings, opening, covered in small black marks. In your hands. You turned one and there were two more. The thing I saw all winter in the dark. I came down on the edge of your book, and my feet said: here." },
        { id = "dark", at = 1400, title = "What the dark knew",
            text = "I don't know how a thing in a case can dream of a book. I have stopped asking. {total} pages now, I have watched open and close. Each time, something in you comes apart a little and is made into something else. I recognise the work." },
        { id = "kept", at = 1800, title = "The quiet side",
            text = "I was a creature who only ate. Then nothing at all, in the dark. Then wings, and I was so afraid the wings were the whole of me. Now you read, and I sit on the page edge with them folded, quiet side out, and you look up and smile anyway. So I have stopped checking my colours. I am here. I am kept." },
